-- Run the entire file in Supabase SQL Editor before deployment.
create extension if not exists pgcrypto;
create table if not exists public.wallets (user_id uuid primary key references auth.users(id) on delete cascade, balance numeric(12,2) not null default 0 check(balance>=0), updated_at timestamptz not null default now());
create table if not exists public.deposits (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount numeric(12,2) not null check(amount>=100 and amount<=100000), transaction_id text not null unique, status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now(), reviewed_at timestamptz, admin_note text);
create index if not exists deposits_user_created_idx on public.deposits(user_id,created_at desc);
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, service_id text not null, service_name text, target_link text not null, quantity integer not null check(quantity>0), charge numeric(12,2) not null check(charge>=0), provider_order_id text, status text not null default 'processing' check(status in ('processing','pending','in_progress','completed','partial','canceled','failed','refunded')), start_count text, remains text, error_message text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists orders_user_created_idx on public.orders(user_id,created_at desc);
create table if not exists public.wallet_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, order_id uuid references public.orders(id) on delete set null, deposit_id uuid references public.deposits(id) on delete set null, kind text not null check(kind in ('deposit','order_charge','order_refund','admin_adjustment')), amount numeric(12,2) not null, note text, created_at timestamptz not null default now());
create index if not exists wallet_transactions_user_created_idx on public.wallet_transactions(user_id,created_at desc);
alter table public.wallets enable row level security; alter table public.deposits enable row level security; alter table public.orders enable row level security; alter table public.wallet_transactions enable row level security;
revoke all on public.wallets from anon,authenticated; revoke all on public.deposits from anon,authenticated; revoke all on public.orders from anon,authenticated; revoke all on public.wallet_transactions from anon,authenticated;
create or replace function public.approve_deposit(p_deposit_id uuid,p_status text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare d public.deposits%rowtype; begin if p_status not in ('approved','rejected') then raise exception 'Invalid status'; end if; select * into d from public.deposits where id=p_deposit_id for update; if not found then raise exception 'Deposit not found'; end if; if d.status<>'pending' then raise exception 'Deposit already reviewed'; end if; update public.deposits set status=p_status,reviewed_at=now(),admin_note=left(coalesce(p_note,''),500) where id=p_deposit_id; if p_status='approved' then insert into public.wallets(user_id,balance) values(d.user_id,d.amount) on conflict(user_id) do update set balance=public.wallets.balance+excluded.balance,updated_at=now(); insert into public.wallet_transactions(user_id,deposit_id,kind,amount,note) values(d.user_id,d.id,'deposit',d.amount,'Admin-approved manual deposit'); end if; return jsonb_build_object('ok',true,'status',p_status,'amount',d.amount,'user_id',d.user_id); end; $$;
create or replace function public.reserve_order(p_user_id uuid,p_service_id text,p_service_name text,p_link text,p_quantity integer,p_charge numeric) returns jsonb language plpgsql security definer set search_path=public as $$ declare b numeric(12,2); o public.orders%rowtype; begin if p_quantity<1 or p_charge<0 then raise exception 'Invalid order values'; end if; insert into public.wallets(user_id,balance) values(p_user_id,0) on conflict(user_id) do nothing; select balance into b from public.wallets where user_id=p_user_id for update; if b<p_charge then raise exception 'Insufficient wallet balance. Required Rs %; available Rs %',p_charge,b; end if; update public.wallets set balance=balance-p_charge,updated_at=now() where user_id=p_user_id; insert into public.orders(user_id,service_id,service_name,target_link,quantity,charge,status) values(p_user_id,p_service_id,left(coalesce(p_service_name,''),200),p_link,p_quantity,p_charge,'processing') returning * into o; insert into public.wallet_transactions(user_id,order_id,kind,amount,note) values(p_user_id,o.id,'order_charge',-p_charge,'Order charge reserved'); return jsonb_build_object('id',o.id,'charge',o.charge,'balance',b-p_charge); end; $$;
create or replace function public.finish_order(p_order_id uuid,p_success boolean,p_provider_order_id text,p_status text,p_error text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.orders%rowtype; begin select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'Order not found'; end if; if o.status<>'processing' then return jsonb_build_object('ok',true,'status',o.status,'duplicate',true); end if; if p_success then update public.orders set provider_order_id=left(coalesce(p_provider_order_id,''),200),status=case when p_status in ('pending','in_progress','completed','partial','canceled','failed','refunded') then p_status else 'pending' end,updated_at=now() where id=p_order_id; else update public.wallets set balance=balance+o.charge,updated_at=now() where user_id=o.user_id; insert into public.wallet_transactions(user_id,order_id,kind,amount,note) values(o.user_id,o.id,'order_refund',o.charge,'Automatic refund: provider rejected order'); update public.orders set status='failed',error_message=left(coalesce(p_error,'Provider rejected order'),500),updated_at=now() where id=p_order_id; end if; return jsonb_build_object('ok',true,'status',case when p_success then p_status else 'failed' end); end; $$;
revoke all on function public.approve_deposit(uuid,text,text) from public,anon,authenticated; revoke all on function public.reserve_order(uuid,text,text,text,integer,numeric) from public,anon,authenticated; revoke all on function public.finish_order(uuid,boolean,text,text,text) from public,anon,authenticated;
grant execute on function public.approve_deposit(uuid,text,text) to service_role; grant execute on function public.reserve_order(uuid,text,text,text,integer,numeric) to service_role; grant execute on function public.finish_order(uuid,boolean,text,text,text) to service_role;
